public void checkI18nPropertyFilesAreInSync() throws java.io.IOException {
    java.util.List<java.nio.file.Path> propertyFiles;
    try (java.util.stream.Stream<java.nio.file.Path> stream = java.nio.file.Files.walk(java.nio.file.Paths.get(org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.I18N_DIR))) {
        propertyFiles = stream.filter((java.nio.file.Path p) -> p.getFileName().toString().startsWith(org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.BASE_NAME)).filter((java.nio.file.Path p) -> p.getFileName().toString().endsWith(org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.PROPERTIES)).toList();
    }
    java.util.Map<java.lang.String, java.util.Properties> localeToProps = new java.util.HashMap<java.lang.String, java.util.Properties>();
    for (java.nio.file.Path path : propertyFiles) {
        java.util.Properties props = new java.util.Properties();
        try (var reader = java.nio.file.Files.newBufferedReader(path)) {
            props.load(reader);
            localeToProps.put(path.getFileName().toString(), props);
        }
    }
    java.lang.String baseFile = org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.BASE_NAME + org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.PROPERTIES;
    java.util.Properties baseProps = localeToProps.get(baseFile);
    if (baseProps == null) {
        org.junit.jupiter.api.Assertions.fail(("Base properties file '" + baseFile) + "' not found.");
        return;
    }
    java.util.Set<java.lang.String> baseKeys = baseProps.stringPropertyNames();
    java.lang.StringBuilder report = new java.lang.StringBuilder();
    for (java.util.Map.Entry<java.lang.String, java.util.Properties> entry : localeToProps.entrySet()) {
        java.lang.String fileName = entry.getKey();
        // We use fallback logic to include english strings, hence messages_en is not
        // populated.
        if (fileName.equals(baseFile) || fileName.equals("messages_en.properties")) {
            continue;
        }
        java.util.Properties props = entry.getValue();
        java.util.Set<java.lang.String> missingKeys = new java.util.TreeSet<java.lang.String>(baseKeys);
        missingKeys.removeAll(props.stringPropertyNames());
        if (!missingKeys.isEmpty()) {
            report.append("Missing keys in ").append(fileName).append(":\n");
            missingKeys.forEach((java.lang.String k) -> report.append("  ").append(k).append("\n"));
        }
    }
    if (!report.isEmpty()) {
        org.junit.jupiter.api.Assertions.fail("Translation files are not in sync:\n" + report);
    }
}

