public void printProperties() {
    for (org.springframework.core.env.EnumerablePropertySource<? extends java.lang.Object> source : this.findPropertiesPropertySources()) {
        org.springframework.samples.petclinic.PostgresIntegrationTests.PropertiesLogger.log.info("PropertySource: " + source.getName());
        java.lang.String[] names = source.getPropertyNames();
        java.util.Arrays.sort(names);
        for (java.lang.String name : names) {
            java.lang.String resolved = this.environment.getProperty(name);
            org.junit.jupiter.api.Assertions.assertNotNull(resolved, ("resolved environment property: " + name) + " is null.");
            java.lang.Object sourceProperty = source.getProperty(name);
            org.junit.jupiter.api.Assertions.assertNotNull(sourceProperty, "source property was expecting an object but is null.");
            org.junit.jupiter.api.Assertions.assertNotNull(sourceProperty.toString(), "source property toString() returned null.");
            java.lang.String value = sourceProperty.toString();
            if (resolved.equals(value)) {
                org.springframework.samples.petclinic.PostgresIntegrationTests.PropertiesLogger.log.info((name + "=") + resolved);
            } else {
                org.springframework.samples.petclinic.PostgresIntegrationTests.PropertiesLogger.log.info((((name + "=") + value) + " OVERRIDDEN to ") + resolved);
            }
        }
    }
}

