    // checking if the pet name already exists for the owner
    if (org.springframework.util.StringUtils.hasText(petName)) {
        org.springframework.samples.petclinic.owner.Pet existingPet = owner.getPet(petName, false);
        if ((existingPet != null) && (!java.util.Objects.equals(existingPet.getId(), pet.getId()))) {
            result.rejectValue("name", "duplicate", "already exists");
        }
    }
    java.time.LocalDate currentDate = java.time.LocalDate.now();
    if ((pet.getBirthDate() != null) && pet.getBirthDate().isAfter(currentDate)) {
        result.rejectValue("birthDate", "typeMismatch.birthDate");
    }
    if (result.hasErrors()) {
        return org.springframework.samples.petclinic.owner.PetController.VIEWS_PETS_CREATE_OR_UPDATE_FORM;
    }
    this.updatePetDetails(owner, pet);
    redirectAttributes.addFlashAttribute("message", "Pet details has been edited");
    return "redirect:/owners/{ownerId}";
}

