void shouldUpdateOwner() {
    java.util.Optional<org.springframework.samples.petclinic.owner.Owner> optionalOwner = this.owners.findById(1);
    org.assertj.core.api.Assertions.assertThat(optionalOwner).isPresent();
    org.springframework.samples.petclinic.owner.Owner owner = optionalOwner.get();
    java.lang.String oldLastName = owner.getLastName();
    java.lang.String newLastName = oldLastName + "X";
    owner.setLastName(newLastName);
    this.owners.save(owner);
    // retrieving new name from database
    optionalOwner = this.owners.findById(1);
    org.assertj.core.api.Assertions.assertThat(optionalOwner).isPresent();
    owner = optionalOwner.get();
    org.assertj.core.api.Assertions.assertThat(owner.getLastName()).isEqualTo(newLastName);
}

