public void checkNonInternationalizedStrings() throws java.io.IOException {
    java.nio.file.Path root = java.nio.file.Paths.get("src/main");
    java.util.List<java.nio.file.Path> files;
    try (java.util.stream.Stream<java.nio.file.Path> stream = java.nio.file.Files.walk(root)) {
        files = stream.filter((java.nio.file.Path p) -> p.toString().endsWith(".java") || p.toString().endsWith(".html")).filter((java.nio.file.Path p) -> !p.toString().contains("/test/")).filter((java.nio.file.Path p) -> !p.getFileName().toString().endsWith("Test.java")).toList();
    }
    java.lang.StringBuilder report = new java.lang.StringBuilder();
    for (java.nio.file.Path file : files) {
        java.util.List<java.lang.String> lines = java.nio.file.Files.readAllLines(file);
        for (int i = 0; i < lines.size(); i++) {
            java.lang.String line = lines.get(i).trim();
            if (((line.startsWith("//") || line.startsWith("@")) || line.contains("log.")) || line.contains("System.out")) {
                continue;
            }
            if (file.toString().endsWith(".html")) {
                boolean hasLiteralText = org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.HTML_TEXT_LITERAL.matcher(line).find();
                boolean hasThTextAttribute = org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.HAS_TH_TEXT_ATTRIBUTE.matcher(line).find();
                boolean isBracketOnly = org.springframework.samples.petclinic.system.I18nPropertiesSyncTest.BRACKET_ONLY.matcher(line).find();
                if (((hasLiteralText && (!line.contains("#{"))) && (!hasThTextAttribute)) && (!isBracketOnly)) {
                    report.append("HTML: ").append(file).append(" Line ").append(i + 1).append(": ").append(line).append("\n");
                }
            }
        }
    }
    if (!report.isEmpty()) {
        org.junit.jupiter.api.Assertions.fail("Hardcoded (non-internationalized) strings found:\n" + report);
    }
}

