    java.util.List<org.springframework.core.env.EnumerablePropertySource<? extends java.lang.Object>> sources = new java.util.LinkedList<org.springframework.core.env.EnumerablePropertySource<? extends java.lang.Object>>();
    for (org.springframework.core.env.PropertySource<? extends java.lang.Object> source : this.environment.getPropertySources()) {
        if (source instanceof org.springframework.core.env.EnumerablePropertySource enumerable) {
            sources.add(enumerable);
        }
    }
    return sources;
}
